/* Minimal team shell. Content belongs to the site; the navigation and look are shared. */
(()=>{
 const copy={th:{intro:'ทุกไอเดีย มีตัวตนของเรา<br>ออกแบบอย่างชัดเจน สร้างอย่างตั้งใจ',explore:'สำรวจผลงาน',work:'ผลงาน',workIntro:'พื้นที่สำหรับผลงาน ภาพ และเรื่องราวของทีม',about:'เกี่ยวกับ',aboutIntro:'เราเชื่อในงานออกแบบที่เรียบง่าย มีเอกลักษณ์ และใช้งานได้จริง',contact:'ติดต่อ',home:'หน้าแรก',projects:'ผลงาน'},en:{intro:'Ideas with an identity.<br>Designed clearly. Made with care.',explore:'Explore our work',work:'Our work',workIntro:'A space for our work, visuals and stories.',about:'About',aboutIntro:'We believe in simple, distinctive design that works.',contact:'Contact',home:'Home',projects:'Projects'},ja:{intro:'アイデアに、私たちらしさを。<br>明快なデザインを、丁寧につくる。',explore:'作品を見る',work:'制作実績',workIntro:'作品、ビジュアル、ストーリーを紹介します。',about:'私たちについて',aboutIntro:'シンプルで個性があり、使いやすいデザインを。',contact:'お問い合わせ',home:'ホーム',projects:'制作実績'},zh:{intro:'让想法拥有独特个性。<br>清晰设计，用心创造。',explore:'浏览作品',work:'作品',workIntro:'展示我们的作品、视觉与故事。',about:'关于我们',aboutIntro:'我们相信简洁、独特且实用的设计。',contact:'联系',home:'首页',projects:'作品'}};
 for(const [language,details] of Object.entries({th:{"typeStudyDesc":"หัวข้ออังกฤษใช้ THE BOLD FONT ภาษาไทยใช้ Kanit 600 (สำรอง Noto Sans Thai) ภาษาญี่ปุ่นใช้ Noto Sans JP และภาษาจีนใช้ Noto Sans SC","colourStudyDesc":"สีหลักของเว็บคือดำเข้มและขาวนวล ใช้แดงเป็นจุดเน้นบนโลโก้ เมนู และปุ่มที่ต้องการให้เห็นชัด"},en:{"typeStudyDesc":"English headings use THE BOLD FONT. Thai uses Kanit 600 with Noto Sans Thai as a fallback; Japanese uses Noto Sans JP and Chinese uses Noto Sans SC.","colourStudyDesc":"Deep black and soft white form the main palette. Red draws attention to the logo, navigation and key actions."},ja:{"typeStudyDesc":"英語見出しに THE BOLD FONT、タイ語に Kanit 600（Noto Sans Thai を補助）、日本語に Noto Sans JP、中国語に Noto Sans SC を使用。","colourStudyDesc":"深い黒と柔らかな白を基本色とし、赤をロゴ、メニュー、重要な操作に使います。"},zh:{"typeStudyDesc":"英文标题使用 THE BOLD FONT，泰文使用 Kanit 600（备用 Noto Sans Thai），日文使用 Noto Sans JP，中文使用 Noto Sans SC。","colourStudyDesc":"深黑与柔白构成主色，红色用于标志、菜单和关键操作。"}}))Object.assign(copy[language],details);
 const menu=document.getElementById('menu'),toggle=document.getElementById('menuToggle');
 function close(focus=false){menu.classList.remove('open');toggle.setAttribute('aria-expanded','false');if(focus)toggle.focus()}
 toggle.addEventListener('click',()=>{const open=!menu.classList.contains('open');menu.classList.toggle('open',open);toggle.setAttribute('aria-expanded',String(open));if(open)menu.querySelector('nav a').focus()});
 document.getElementById('closeMenu').addEventListener('click',()=>close(true));menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>close()));
 document.addEventListener('click',e=>{if(!menu.contains(e.target)&&!toggle.contains(e.target))close()});document.addEventListener('focusin',e=>{if(!menu.contains(e.target)&&!toggle.contains(e.target))close()});document.addEventListener('keydown',e=>{if(e.key==='Escape')close(true)});
 document.querySelectorAll('[data-lang]').forEach(button=>button.addEventListener('click',()=>{const language=button.dataset.lang,dictionary=copy[language];document.documentElement.lang=language;document.querySelectorAll('[data-starter-copy],[data-t]').forEach(e=>{const value=dictionary[e.dataset.starterCopy||e.dataset.t];if(value)e.innerHTML=value});document.querySelectorAll('[data-lang]').forEach(e=>e.classList.toggle('selected',e===button))}));
 const up=document.getElementById('backToTop');function scroll(){const show=window.scrollY>window.innerHeight*.5;up.classList.toggle('is-visible',show);up.tabIndex=show?0:-1}window.addEventListener('scroll',scroll,{passive:true});scroll();
})();
function clock(){const now=new Date(),date=document.getElementById('logoDate');date.textContent=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Bangkok',day:'2-digit',month:'short',year:'numeric'}).format(now).toUpperCase();const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now);date.dateTime=['year','month','day'].map(key=>parts.find(part=>part.type===key).value).join('-');document.getElementById('clock').textContent=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Bangkok',hour:'2-digit',minute:'2-digit'}).format(new Date())+' UTC+7'}clock();setInterval(clock,60000);

